patches.payload:
/* HITHER-LANDS:shape-decl BEGIN */
uint8_t *shape_x_attr;
wchar_t *shape_x_char;
/* HITHER-LANDS:shape-decl END */

/* HITHER-LANDS:shape-parser BEGIN */
static enum parser_error parse_prefs_shape(struct parser *p)
{
	const char *name;
	struct player_shape *shape;

	struct prefs_data *d = parser_priv(p);
	assert(d != NULL);
	if (d->bypass) return PARSE_ERROR_NONE;

	name = parser_getsym(p, "name");
	shape = lookup_player_shape(name);
	if (!shape)
		return PARSE_ERROR_NO_KIND_FOUND;

	shape_x_attr[shape->sidx] = (uint8_t)parser_getint(p, "attr");
	shape_x_char[shape->sidx] = (wchar_t)parser_getint(p, "char");

	return PARSE_ERROR_NONE;
}
/* HITHER-LANDS:shape-parser END */

/* HITHER-LANDS:shape-reg BEGIN */
parser_reg(p, "shape sym name int attr int char", parse_prefs_shape);
/* HITHER-LANDS:shape-reg END */

/* HITHER-LANDS:shape-alloc BEGIN */
shape_x_attr = mem_zalloc(z_info->shape_max * sizeof(uint8_t));
shape_x_char = mem_zalloc(z_info->shape_max * sizeof(wchar_t));
/* HITHER-LANDS:shape-alloc END */

/* HITHER-LANDS:shape-free BEGIN */
mem_free(shape_x_attr);
mem_free(shape_x_char);
/* HITHER-LANDS:shape-free END */

/* HITHER-LANDS:shape-reset BEGIN */
/* Shapes carry no ASCII default; clear so only graphic prf sets them */
for (i = 0; i < z_info->shape_max; i++) {
	shape_x_attr[i] = 0;
	shape_x_char[i] = 0;
}
/* HITHER-LANDS:shape-reset END */

/* HITHER-LANDS:shape-export BEGIN */
extern uint8_t *shape_x_attr;
extern wchar_t *shape_x_char;
/* HITHER-LANDS:shape-export END */

/* HITHER-LANDS:shape-render-grid BEGIN */
if (player->shape && shape_x_attr[player->shape->sidx]) {
	a = shape_x_attr[player->shape->sidx];
	c = shape_x_char[player->shape->sidx];
}
/* HITHER-LANDS:shape-render-grid END */

